import type { CSSObject } from '@emotion/react';
import styled from '@emotion/styled';
import { Chip, SearchField } from '@hexa-ui/components';
import { Heading } from 'components/UI';
import { theme } from 'theme';

export const StyledPillarResourcesContainer = styled.div({
  display: 'flex',
  flexDirection: 'column',
  gap: '16px',
  padding: '0 24px 24px 24px',
});

export const StyledPillarResourcesActions = styled.div({
  display: 'flex',
  flexDirection: 'row',
  gap: '8px',
});

export const StyledPillarResourcesContent = styled.div({
  display: 'flex',
  flexDirection: 'row',
  gap: '16px',
  flexWrap: 'wrap',
});

const noFavoritesFoundStyles = {
  width: '100%',
  padding: theme.spacing['6'],
  textAlign: 'center',
  fontFamily: theme.fonts.paragraph,
  fontSize: theme.fonts.fontSizes['3'],
  color: theme.colors.neutral80,
} as unknown as CSSObject;

export const StyledNoFavoritesFound = styled(Heading)(noFavoritesFoundStyles);

const noResultsFoundStyles = {
  width: '100%',
  padding: theme.spacing['6'],
  textAlign: 'center',
  fontFamily: theme.fonts.paragraph,
  fontSize: theme.fonts.fontSizes['3'],
  color: theme.colors.neutral80,
} as unknown as CSSObject;

export const StyledNoResultsFound = styled(Heading)(noResultsFoundStyles);

export const StyledPillarResourcesSearch = styled(SearchField.Root)<{
  size?: 'medium';
}>(({ size }) => ({
  ...(size === 'medium' && { height: '32px' }),
}));

interface PillarResourcesFilterButtonProps {
  $selected?: boolean;
}

export const PillarResourcesFilterButton = styled(Chip.Root, {
  shouldForwardProp: (prop) => prop !== '$selected',
})<PillarResourcesFilterButtonProps>(({ $selected }) => ({
  padding: `${theme.spacing['2']} 12px`,
  height: '39px',
  marginRight: '1px',
  ...($selected && {
    outlineColor: 'rgba(0, 110, 219, 1)',
    p: {
      color: 'rgba(0, 110, 219, 1)',
    },
    svg: {
      color: 'rgba(0, 110, 219, 1)',
    },
  }),
}));

export const PillarResourcesFilterLabel = styled(Chip.Label)({
  display: 'flex',
  gap: 8,
});
